const touchAgentBySerial = `-- name: TouchAgentBySerial :exec
UPDATE host_agents SET last_seen = now(), version = $1,
  connected_since = CASE
    WHEN connected_since IS NULL
      OR (last_seen IS NOT NULL
          AND last_seen < now() - make_interval(secs => $2::double precision))
    THEN now() ELSE connected_since END,
  online_since = CASE
    WHEN last_seen IS NULL OR online_since IS NULL
      OR last_seen < now() - make_interval(secs => LEAST($3::double precision,
          GREATEST($4::double precision,
            $5::double precision * COALESCE(heartbeat_interval_s, 0))))
    THEN now() ELSE online_since END
WHERE cert_serial = $6
`

type TouchAgentBySerialParams struct {
	Version                   string  `json:"version"`
	ReconnectGapSeconds       float64 `json:"reconnect_gap_seconds"`
	BufferWindowSeconds       float64 `json:"buffer_window_seconds"`
	OnlineWindowFloorSeconds  float64 `json:"online_window_floor_seconds"`
	HeartbeatsPerOnlineWindow float64 `json:"heartbeats_per_online_window"`
	Serial                    string  `json:"serial"`
}

// Org-unscoped heartbeat by serial: the gRPC stream has no org context
// (the serial is the secret and is globally unique). The stream's open and
// ingest pacing touch with this; they carry no secrets report, so the
// stored one stays.
//
// connected_since (00088, backlog 3.12c) is when the agent's current
// connection began: kept while each touch follows the previous one within
// the reconnect gap (agents' reconnectGap, 24 h), set to now() on the
// first touch after a longer gap or when it is unknown (NULL: after an
// enrollment, a registration after a longer gap — UpsertHostAgent — and
// on every row right after the upgrade). A NULL last_seen with a known
// start is a certificate renewal within the gap, which keeps it. The SET
// list reads the row as it was before this update, so last_seen here is
// the previous touch. The item expiry counts the agent only after
// checks.MaxInterval plus a 30-minute margin connected.
//
// online_since (00092, backlog 3.57) is when the agent's current online
// period began, which an online client host's staleness is measured from:
// kept while the previous touch is within the agents list's online window,
// set to now() after a longer gap, after a registration (last_seen NULL)
// and when it is unknown. The window is the row's own (agents.OnlineWindow,
// backlog 3.58): heartbeats_per_online_window of the agent's reported
// heartbeat interval (heartbeat_interval_s, 00119), never less than
// online_window_floor_seconds, which is the whole window when the agent
// never reported its interval. The gap that restarts the period is also
// capped at buffer_window_seconds (agents.DisconnectBufferWindow): after
// a gap the agent's disconnect buffer could not hold, its replay has lost
// the head of the gap, and the replay hold (backlog 3.118) only arms on a
// new period. The online verdict keeps the full window.
func (q *Queries) TouchAgentBySerial(ctx context.Context, arg TouchAgentBySerialParams) error {
	_, err := q.db.Exec(ctx, touchAgentBySerial,
		arg.Version,
		arg.ReconnectGapSeconds,
		arg.BufferWindowSeconds,
		arg.OnlineWindowFloorSeconds,
		arg.HeartbeatsPerOnlineWindow,
		arg.Serial,
	)
	return err
}

const upsertFactTag = `-- name: UpsertFactTag :exec
INSERT INTO host_tags (host_id, org_id, key, value, source)
SELECT $1, $2, $3, $4, 'fact'
WHERE NOT EXISTS (
  SELECT 1 FROM host_tags
  WHERE host_id = $1 AND key = $3 AND source = 'manual'
)
ON CONFLICT (host_id, key, source) DO UPDATE SET value = EXCLUDED.value
`

type UpsertFactTagParams struct {
	HostID uuid.UUID `json:"host_id"`
	OrgID  uuid.UUID `json:"org_id"`
	Key    string    `json:"key"`
	Value  string    `json:"value"`
}

// One automatic fact tag (source = 'fact'): the guarded upsert — a manual
// row for the same key ALWAYS wins, so the SELECT produces no row while
// the operator's tag exists (nothing inserted, nothing updated), a manual
// row that was removed re-admits the fact on the next push, and an
// existing fact row is updated in place. The guard and the conflict
// target are both (host_id, key): source is part of the primary key, so a
// manual and a fact row for the same key coexist by design (00011) and
// every reader merges them with manual winning.
func (q *Queries) UpsertFactTag(ctx context.Context, arg UpsertFactTagParams) error {
	_, err := q.db.Exec(ctx, upsertFactTag,
		arg.HostID,
		arg.OrgID,
		arg.Key,
		arg.Value,
	)
	return err
}

const upsertHostAgent = `-- name: UpsertHostAgent :one
INSERT INTO host_agents (host_id, org_id, agent_name, cert_serial, version)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (host_id) DO UPDATE
SET agent_name = EXCLUDED.agent_name, cert_serial = EXCLUDED.cert_serial,
    version = EXCLUDED.version, last_seen = NULL, created_at = now(),
    connected_since = CASE
      WHEN host_agents.last_seen >= now() - make_interval(secs => $6::double precision)
      THEN host_agents.connected_since END,
    online_since = NULL,
    secret_names = CASE WHEN $7::boolean THEN host_agents.secret_names END,
    secrets_state = CASE WHEN $7::boolean THEN host_agents.secrets_state END,
    local_checks = CASE WHEN $7::boolean THEN host_agents.local_checks END,
    local_check_problems = CASE WHEN $7::boolean THEN host_agents.local_check_problems END,
    config_version = NULL, config_expected = NULL, config_checked_at = NULL
RETURNING host_id, org_id, agent_name, cert_serial, last_seen, version, created_at, secret_names, secrets_state, connected_since, config_version, config_expected, config_checked_at, online_since, local_checks, local_check_problems, probes_supported, heartbeat_interval_s
`

type UpsertHostAgentParams struct {
	HostID              uuid.UUID `json:"host_id"`
	OrgID               uuid.UUID `json:"org_id"`
	AgentName           string    `json:"agent_name"`
	CertSerial          string    `json:"cert_serial"`
	Version             string    `json:"version"`
	ReconnectGapSeconds float64   `json:"reconnect_gap_seconds"`
	KeepReports         bool      `json:"keep_reports"`
}

// The active agent of a host: re-enrollment and certificate renewal both
// replace the row in place (ON CONFLICT on the host primary key), so
// exactly one agent row exists per host at any time. agent_certificates
// carries the previous serials — the service marks the old one revoked in
// the same transaction. Like last_seen, the configuration check (00089)
// starts over: the new registration has not been compared yet. The
// agent's reports — secrets (00086) and local checks (00095), which the
// heartbeat writes together — start over on a re-enrollment, which may be
// another agent, and are kept when keep_reports is set: a certificate
// renewal is the same agent on a new serial, so what it last said about
// its agent.yaml still holds, and resetting would leave its local checks
// unresolved (their tuples unmeasured, their open alerts closed) until its
// next heartbeat. The connection start (00088,
// backlog 3.12c) is kept when the previous registration was last seen
// within the reconnect gap — a renewal happens on a live connection, every
// ~60 days, and must not restart the item expiry's wait — and otherwise
// becomes NULL, so the first touch sets it (TouchAgentBySerial). The SET
// list reads the row as it was before this update. The online period
// (online_since, 00092, backlog 3.57) always starts over: last_seen is
// NULL now, and the first touch under the new serial starts a new one.
func (q *Queries) UpsertHostAgent(ctx context.Context, arg UpsertHostAgentParams) (HostAgent, error) {
	row := q.db.QueryRow(ctx, upsertHostAgent,
		arg.HostID,
		arg.OrgID,
		arg.AgentName,
		arg.CertSerial,
		arg.Version,
		arg.ReconnectGapSeconds,
		arg.KeepReports,
	)
	var i HostAgent
	err := row.Scan(
		&i.HostID,
		&i.OrgID,
		&i.AgentName,
		&i.CertSerial,
		&i.LastSeen,
		&i.Version,
		&i.CreatedAt,
		&i.SecretNames,
		&i.SecretsState,
		&i.ConnectedSince,
		&i.ConfigVersion,
		&i.ConfigExpected,
		&i.ConfigCheckedAt,
		&i.OnlineSince,
		&i.LocalChecks,
		&i.LocalCheckProblems,
		&i.ProbesSupported,
		&i.HeartbeatIntervalS,
	)
	return i, err
}

const upsertHostFacts = `-- name: UpsertHostFacts :execrows
UPDATE hosts SET
  facts = CASE
    WHEN (SELECT count(*) FROM jsonb_object_keys(COALESCE(facts, '{}'::jsonb) || $1::jsonb)) <= $2::integer
      THEN COALESCE(facts, '{}'::jsonb) || $1::jsonb
    ELSE $1::jsonb
  END,
  updated_at = now()
WHERE id = $3 AND org_id = $4
`

type UpsertHostFactsParams struct {
	Facts   []byte    `json:"facts"`
	MaxKeys int32     `json:"max_keys"`
	HostID  uuid.UUID `json:"host_id"`
	OrgID   uuid.UUID `json:"org_id"`
}

// The facts push's merge (RecordFacts, Task 8): the jsonb || concatenation
// is an object merge where the RIGHT side wins for duplicate keys — every
// reported key REPLACES its previous value, every key the agent did not
// report survives untouched. That asymmetry is the semantics on purpose:
// the agent sends the complete set each push, so an unreported key is a
// stale fact from an older agent version, and keeping it (instead of
// deleting it) is the simplest honest behavior — the operator still sees
// what the host used to report. Stale keys are kept only while the
// merged object stays at or under max_keys (agents.MaxStoredFacts, backlog
// 7.56): a push whose merge would exceed it REPLACES the stored set with
// the reported one, so keys can never accumulate without bound across
// pushes. A set already above the cap (stored before it existed) is
// replaced by the next push the same way. 0 affected rows is the caller's
// ErrNotFound (unknown host, or one belonging to another organization).
func (q *Queries) UpsertHostFacts(ctx context.Context, arg UpsertHostFactsParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertHostFacts,
		arg.Facts,
		arg.MaxKeys,
		arg.HostID,
		arg.OrgID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
